//! 🧪️ The actual history ledger exposes all original inverses until one shared decision commits, and exact original factories close every displaced owner.
use super::*;
use crate::CursorRevisionRecord;
use semio_framework_os_vcs::{ArtifactGroupVisibilityOwner,HistoryPageStack};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use std::sync::atomic::{AtomicU64,Ordering};
static RETIRED:AtomicU64=AtomicU64::new(0);
#[derive(semio_framework_value::RetireOwned)]
struct Marker{bytes:Vec<u8>}
#[derive(semio_framework_value::FactoryPayloadRetirement)]
struct Issuer;
impl ArtifactOwnedValueRetirementFactory<Marker> for Issuer{fn retirement_birth_bytes(&self,_:&Marker)->usize{semio_framework_value::owned_retirement_birth_bytes::<Marker>()}fn retire_owned(&self,original:Marker,g:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,Marker)>{RETIRED.fetch_or(1<<original.bytes[0],Ordering::Relaxed);semio_framework_value::admit_owned_retirement(original,g)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn denied(mut g:RetainedCloneGrant,axis:&str)->RetainedCloneGrant{match axis{"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes=0,"capacity"=>g.maximum_capacity_bytes=0,"release"=>g.maximum_release_bytes=0,_=>g.maximum_depth=0}g}
fn exact(p:RetainedCloneProgress,h:semio_framework_trace::HeapAllocationObservation){assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
#[test]
fn original_replay_inverse_settlement_stages_no_clone_rows_and_retires_same_issuer_after_atomic_decision(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let maximum=law["maximumTurns"].as_u64().unwrap()as usize;for(commit,prefix)in [(false,0),(false,1),(false,2),(true,2)]{RETIRED.store(0,Ordering::Relaxed);let mut edits=ArtifactHistoryLedger::new();let mut revision=CursorRevisionAccumulator{identity_digest:[0;32],applied:HistoryPageStack::empty(),redo:HistoryPageStack::empty(),applied_tail_chains:None,mutation_positions:Default::default(),indexed_edits:Default::default(),unit_flags:Default::default()};let mut rows=Vec::new();let mut pointers=Vec::new();for(position,row)in law["edits"].as_array().unwrap().iter().enumerate(){let id=row["id"].as_str().unwrap().to_owned();let original=Marker{bytes:vec![row["original"].as_u64().unwrap()as u8;33]};let candidate=Marker{bytes:vec![row["candidate"].as_u64().unwrap()as u8;65]};pointers.push((original.bytes.as_ptr(),candidate.bytes.as_ptr()));let edit=Edit{id:id.clone(),actor:None,line:None,forwards:Vec::new(),inverse:vec![original].into(),mutation_meta:Vec::new(),verb:None,sequence_number:position as i32,started_at:String::new(),finished_at:None};let key=edits.try_push(edit).ok().unwrap();let digest=CursorRevisionAccumulator::hash_record(b"edit-id",&[id.as_bytes()]);revision.applied.push(CursorRevisionRecord::new(Some(key),digest,[0;32],[0;32]));revision.indexed_edits.insert(digest,(position,0));rows.push((id,vec![candidate].into()));}let source_pointer=rows.as_ptr();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Marker>>=Arc::new(Issuer);let mut gate=ArtifactGroupVisibilityOwner::new();let view=gate.view();let mut owner=ArtifactReplayInverseSettlement::default();let d=ArtifactReplayInverseSettlement::<Marker>::capture_demands();for axis in ["items","copy","depth"]{let(p,h)=observe(||owner.capture(&edits,&mut rows,&factory,&view,denied(grant(d),axis)).unwrap());exact(p,h);assert_eq!(p,Default::default());assert_eq!(rows.as_ptr(),source_pointer);}let(p,h)=observe(||owner.capture(&edits,&mut rows,&factory,&view,grant(d)).unwrap());exact(p,h);assert!(rows.is_empty());assert_eq!(owner.rows.as_ref().unwrap().as_ptr(),source_pointer);let mut foreign=ArtifactHistoryLedger::empty();let(error,h)=observe(||owner.prepare_next(&mut foreign,&revision,grant(owner.preparation_demands())).unwrap_err());assert_eq!(error.retained_progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));for _ in 0..prefix{let d=owner.preparation_demands();for axis in law["deniedAxes"].as_array().unwrap(){let(p,h)=observe(||owner.prepare_next(&mut edits,&revision,denied(grant(d),axis.as_str().unwrap())).unwrap());exact(p,h);assert_eq!(p,Default::default());}let(p,h)=observe(||owner.prepare_next(&mut edits,&revision,grant(d)).unwrap());exact(p,h);for(index,edit)in edits.iter().enumerate(){assert_eq!(edit.inverse[0].bytes.as_ptr(),pointers[index].0);}}assert_eq!(owner.staged_rows(),prefix);if commit{assert!(owner.prepared());assert!(gate.commit());}else{assert!(gate.abort());}for(index,edit)in edits.iter().enumerate(){assert_eq!(edit.inverse[0].bytes.as_ptr(),if commit{pointers[index].1}else{pointers[index].0});}for turn in 0..maximum{if owner.terminal_is_empty(){break}let d=owner.close_demands(&edits,&revision,4096).unwrap();for axis in ["items","copy","capacity","release","depth"]{let value=match axis{"items"=>1,"copy"=>d.copy_bytes,"capacity"=>d.capacity_bytes,"release"=>d.release_bytes,_=>d.depth};if value==0{continue}let(step,h)=observe(||owner.close_next(&mut edits,&revision,denied(grant(d),axis)));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));match step{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.retained_progress(),Default::default())}}let(step,h)=observe(||owner.close_next(&mut edits,&revision,grant(d)).unwrap());exact(step.progress(),h);assert!(turn+1<maximum);}assert!(owner.terminal_is_empty());assert_eq!(RETIRED.load(Ordering::Relaxed),if commit{(1<<3)|(1<<5)}else{(1<<7)|(1<<11)});for(index,edit)in edits.iter().enumerate(){assert!(!edit.inverse.has_staged_root());assert_eq!(edit.inverse[0].bytes.as_ptr(),if commit{pointers[index].1}else{pointers[index].0});}while let Some(edit)=edits.pop(){let mut close=crate::edit_retirement::ArtifactStoreDecodedEditRetirement::new(edit,Arc::clone(&factory));for turn in 0..maximum{if close.terminal_is_empty(){break}let d=close.demands(4096).unwrap();let(step,h)=observe(||close.close_step(grant(d)).unwrap());exact(step.progress(),h);assert!(turn+1<maximum);}assert!(close.terminal_is_empty());}while edits.retained_terminal_slot_count()>0{let((view,p),h)=observe(||edits.retire_terminal_slot(grant(RetirementDemand{depth:1,..Default::default()})).unwrap());exact(p,h);assert!(view.is_none());}while !edits.backing_is_empty(){let d=RetirementDemand{release_bytes:edits.next_empty_page_release_byte_demand().unwrap(),depth:1,..Default::default()};let(step,h)=observe(||edits.release_empty_page(grant(d)).unwrap());exact(step.progress(),h);}drop(edits);drop(owner);drop(view);drop(gate);drop(factory);}
}
